solutionCode:
class Box<T>(private val item: T) {
    fun getValue(): T {
        return item
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testIntBox() {
        val box = Box<Int>(42)
        Assert.assertEquals(42, box.getValue())
    }

    @Test
    fun testStringBox() {
        val box = Box<String>("Tribots")
        Assert.assertEquals("Tribots", box.getValue())
    }

    @Test
    fun testDoubleBox() {
        val box = Box<Double>(3.14)
        Assert.assertEquals(3.14, box.getValue(), 0.001)
    }
}
